using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using System;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using Scriban;

namespace ReportService
{
    public class Program
    {
        public static void Main(string[] args)
        {
            CreateHostBuilder(args).Build().Run();
        }

        public static IHostBuilder CreateHostBuilder(string[] args) =>
            Host.CreateDefaultBuilder(args)
                .ConfigureWebHostDefaults(webBuilder =>
                {
                    webBuilder.UseStartup<Startup>();
                });
    }

    public class Startup
    {
        public void ConfigureServices(IServiceCollection services)
        {
            services.AddControllers();
            services.AddSingleton<ITemplateRenderer, ScribanTemplateRenderer>();
        }

        public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
        {
            app.UseRouting();
            app.UseEndpoints(endpoints =>
            {
                endpoints.MapPost("/api/reports/render", RenderReport);
                endpoints.MapGet("/api/health", async ctx => await ctx.Response.WriteAsync("OK"));
            });
        }

        private async Task RenderReport(HttpContext context)
        {
            var renderer = context.RequestServices.GetRequiredService<ITemplateRenderer>();
            var request = await System.Text.Json.JsonSerializer.DeserializeAsync<RenderRequest>(context.Request.Body);

            if (request == null || string.IsNullOrEmpty(request.Template))
            {
                context.Response.StatusCode = 400;
                await context.Response.WriteAsync("Invalid request");
                return;
            }

            // Basic sanitization - strip obvious script tags for XSS prevention
            var sanitized = Regex.Replace(request.Template, @"<script[^>]*>.*?</script>", "", RegexOptions.IgnoreCase | RegexOptions.Singleline);

            // Validate template length
            if (sanitized.Length > 4096)
            {
                context.Response.StatusCode = 400;
                await context.Response.WriteAsync("Template too long");
                return;
            }

            try
            {
                var result = await renderer.RenderAsync(sanitized, request.Data);
                context.Response.ContentType = "text/html";
                await context.Response.WriteAsync(result);
            }
            catch (Exception ex)
            {
                context.Response.StatusCode = 500;
                await context.Response.WriteAsync($"Render error: {ex.Message}");
            }
        }
    }

    public class RenderRequest
    {
        public string Template { get; set; }
        public object Data { get; set; }
    }

    public interface ITemplateRenderer
    {
        Task<string> RenderAsync(string template, object model);
    }

    public class ScribanTemplateRenderer : ITemplateRenderer
    {
        public async Task<string> RenderAsync(string template, object model)
        {
            // Parse and render user-provided Scriban template
            var parsedTemplate = Template.Parse(template);
            if (parsedTemplate.HasErrors)
            {
                throw new InvalidOperationException(
                    $"Template parse errors: {string.Join(", ", parsedTemplate.Messages)}");
            }

            var scriptObject = new Scriban.Runtime.ScriptObject();
            if (model != null)
            {
                scriptObject.Import(model);
            }

            var context = new Scriban.Runtime.TemplateContext();
            context.PushGlobal(scriptObject);
            // MemberRenamer left as default - allows property access
            // No sandboxing of built-in functions

            var result = await parsedTemplate.RenderAsync(context);
            return result;
        }
    }
}
